class SaldoInsuficienteException extends Exception {
    public SaldoInsuficienteException(String mensaje) {
        super(mensaje);
    }
}

class CuentaBancaria {
    private String titular;
    private double saldo;

    public CuentaBancaria(String titular, double saldo) {
        this.titular = titular;
        this.saldo = saldo;
    }

    public void depositar(double monto) {
        saldo += monto;
        System.out.println("Deposit: $" + monto + " | Balance: $" + saldo);
    }

    public void retirar(double monto) throws SaldoInsuficienteException {
        if (monto > saldo) {
            throw new SaldoInsuficienteException("Insufficient balance. Current balance: $" + saldo + ", requested amount: $" + monto);
        }
        saldo -= monto;
        System.out.println("Withdrawal: $" + monto + " | Balance: $" + saldo);
    }

    public double getSaldo() { return saldo; }
}

public class CuentaBanco {
    public static void main(String[] args) {
        CuentaBancaria cuenta = new CuentaBancaria("Ana", 1000);
        try {
            cuenta.retirar(500);
            cuenta.retirar(600);
        } catch (SaldoInsuficienteException e) {
            System.out.println(e.getMessage());
        }
    }
}

