class ErrorCodeException extends Exception {
    private int codigoError;

    public ErrorCodeException(String mensaje, int codigoError) {
        super(mensaje);
        this.codigoError = codigoError;
    }

    public int getCodigoError() {
        return codigoError;
    }
}

public class ValidadorOperacion {
    public static void validarOperacion(String datos, String tipo) throws ErrorCodeException {
        if (datos == null) {
            throw new ErrorCodeException("Data cannot be null", 1001);
        }
        if (!datos.matches("[a-zA-Z0-9]+")) {
            throw new ErrorCodeException("Invalid data format: " + datos, 1002);
        }
        if (tipo.equals("denegado")) {
            throw new ErrorCodeException("Access denied for type: " + tipo, 1003);
        }
        System.out.println("Valid operation. Data: " + datos + ", Type: " + tipo);
    }

    public static void main(String[] args) {
        String[][] pruebas = {
            {null, "normal"},
            {"datos@invalidos", "normal"},
            {"datos123", "denegado"},
            {"datos123", "normal"}
        };
        for (String[] prueba : pruebas) {
            try {
                validarOperacion(prueba[0], prueba[1]);
            } catch (ErrorCodeException e) {
                System.out.println("Error [" + e.getCodigoError() + "]: " + e.getMessage());
            }
        }
    }
}

