class ValidationException extends Exception {
    private String campo;

    public ValidationException(String mensaje, String campo) {
        super(mensaje);
        this.campo = campo;
    }

    public String getCampo() {
        return campo;
    }
}

class EmailValidationException extends ValidationException {
    public EmailValidationException(String mensaje) {
        super(mensaje, "email");
    }
}

class AgeValidationException extends ValidationException {
    public AgeValidationException(String mensaje) {
        super(mensaje, "edad");
    }
}

public class ValidadorJerarquico {
    public static void validarUsuario(String email, int edad) throws ValidationException {
        if (email == null) {
            throw new EmailValidationException("Email cannot be null");
        }
        if (!email.contains("@")) {
            throw new EmailValidationException("Email must contain '@': " + email);
        }
        if (edad < 0 || edad > 150) {
            throw new AgeValidationException("Age must be between 0 and 150: " + edad);
        }
        System.out.println("Valid user - Email: " + email + ", Age: " + edad);
    }

    public static void main(String[] args) {
        Object[][] pruebas = {
            {"ana@mail.com", 25},
            {null, 25},
            {"bob", 25},
            {"carlos@mail.com", -5},
            {"diana@mail.com", 200},
            {null, -1}
        };
        for (Object[] prueba : pruebas) {
            try {
                validarUsuario((String) prueba[0], (int) prueba[1]);
            } catch (EmailValidationException e) {
                System.out.println("Error in field [" + e.getCampo() + "]: " + e.getMessage());
            } catch (AgeValidationException e) {
                System.out.println("Error in field [" + e.getCampo() + "]: " + e.getMessage());
            } catch (ValidationException e) {
                System.out.println("Validation error [" + e.getCampo() + "]: " + e.getMessage());
            }
        }
    }
}
